SourceCode.Declaration:
class TFMMenuItemStateConfiguration
{
    str										menuItemName;
    str										icon;
    real									promoted;
    str										title;
    boolean									enabled;
    boolean									titleChanged;
    TFMPage									pageMenuItemPointsTo;
    TFMPageActionAttribute					pageActionAttribute;
    TFMPageMenuItemsAdditionalProperties	additionalProperties;

}

Method.Source:
public str parmMenuItemName(str _menuItemName = menuItemName)
{
    menuItemName = _menuItemName;
    return menuItemName;
}

public real parmPromoted(real _promoted = promoted)
{
    promoted = _promoted;
    return promoted;
}

public boolean parmEnabled(boolean _enabled = enabled)
{
    enabled = _enabled;
    return enabled;
}

public TFMPageMenuItemsAdditionalProperties parmAdditionalProperties(TFMPageMenuItemsAdditionalProperties _additionalProperties = additionalProperties)
{
    additionalProperties = _additionalProperties;
    return additionalProperties;
}

public TFMPage parmPageMenuItemPointsTo(TFMPage _page = pageMenuItemPointsTo)
{
    pageMenuItemPointsTo = _page;
    if(!pageMenuItemPointsTo && menuItemName)
    {
        pageMenuItemPointsTo = TFMPagesProvider::getAllPages().getPage(menuItemName); // since the page pointed to is not necessarily created at the time there is a check here and not in the constructor of the class.
    }
    return pageMenuItemPointsTo;
}

	public str parmTitle(str _title = title)
    {
        if (title != _title && _title)
        {
            titleChanged = true;
        }
        title = _title;
        if(!title)
        {
            // if the title was not set then use the page if any.
            if(this.parmPageMenuItemPointsTo() && pageMenuItemPointsTo.parmTitle())
            {
                title = pageMenuItemPointsTo.parmTitle();
            }
        }

        return title;
    }

public str parmIcon(str _icon = icon)
{
    icon = _icon;
    if(!icon)
    {
        // if the icon was not set then use the page if any.
        if(this.parmPageMenuItemPointsTo() && pageMenuItemPointsTo.parmIcon())
        {
            icon = pageMenuItemPointsTo.parmIcon();
        }
    }
    return icon;
}

protected void new(str _menuItemName, real _promoted = -1, TFMPageActionAttribute _pageActionAttribute = null)
{
    menuItemName = _menuItemName;
    promoted = _promoted;
    enabled = true;
    pageActionAttribute = _pageActionAttribute;
    if(!pageActionAttribute)
    {
        // Create default _pageAction we default to an open action.
        pageActionAttribute = new TFMPageActionAttribute(TFMPageMenuItemTypes::OpenAction, '', _promoted > -1, false);

    }
}

public static TFMMenuItemStateConfiguration Construct(str _menuItemName, real _promoted = -1, TFMPageActionAttribute _pageActionAttribute = null)
{
    return new TFMMenuItemStateConfiguration(_menuItemName,_promoted, _pageActionAttribute);
}

    /// <summary>
    /// Appends the menuItems to the response data for the data elements e.g. in orderlines.
    /// </summary>
	public void appendToXML(XmlElement _element)
    {
        XmlElement menuItemElement = _element.ownerDocument().createElement(TFMMenuItemStateConfiguration::GetDataMemberNameAcceptableForXml(menuItemName));
		if (promoted >-1 )
        {
            menuItemElement.setAttribute('promoted', int2Str(promoted));
        }
        menuItemElement.setAttribute('enabled', enabled ? 'true' : 'false');

        _element.appendChild(menuItemElement);
    }

public static str GetDataMemberNameAcceptableForXml(str _menuItemName)
{
    return strReplace(_menuItemName, "/", "_");
}

public static TFMMenuItemStateConfiguration makeAdhocAction(str _menuitemName, TFMDocumentTypeId _documentTypeId, TFMDocumentContentSubject _contentType, str _icon, str _title, boolean _refreshOnSuccess, TFMPageID _navigateToOnSuccesfulPost = '')
{
    TFMMenuItemStateConfiguration				conf;
    TFMPageActionAttribute						pageAction;
    TFMPageAdhocMenuItemsAdditionalProperties	additionalProps;

    pageAction = new TFMPageActionAttribute(TFMPageMenuItemTypes::AdhocAction,_icon,-1,false);

    additionalProps = new TFMPageAdhocMenuItemsAdditionalProperties();
    additionalProps.parmDocumentType(_documentTypeId);
    additionalProps.parmContentType(_contentType);
    additionalProps.parmRefreshOnSuccess(_refreshOnSuccess);
    additionalProps.parmNavigateTo(_navigateToOnSuccesfulPost);

    conf = TFMMenuItemStateConfiguration::Construct(_menuitemName, -1, pageAction);
    conf.parmAdditionalProperties(additionalProps);
    conf.parmTitle(_title);




    return conf;
}
